<?php
$iv=$selectedInvoice;
$draft=[];
foreach(['seller','buyer'] as $party)foreach(['name','ico','street','city','postal_code','email','phone','bank_account'] as $key)$draft[$party.'_'.$key]=$iv[$party][$key]??'';
$draft=array_replace($draft,$iv);
if($accountingError!=='' && ($_POST['action']??'')==='evidence-invoice-save')$draft=array_replace($draft,$_POST);
$ivf=static fn(string $key):string=>is_scalar($draft[$key]??null)?(string)$draft[$key]:'';
?>
<details class="panel-panel" <?= $accountingError!=='' && ($_POST['action']??'')==='evidence-invoice-save'?'open':'' ?>><summary>Upravit údaje a obsah vystavené faktury</summary>
<p>Pro vrácení nebo snížení ceny použij navazující opravný doklad níže. Přímá úprava je dostupná například pro chybný údaj nebo testovací fakturu; předchozí verze se uchová. Změněnou verzi případně předej zákazníkovi a ověř soulad s objednávkou a platbami.</p>
<form class="panel-form panel-evidence-form" method="post" action="<?= \SimpleStore\Navigation\PanelUrl::escape($taxUrl.'&tab=invoices&invoice_id='.(int)$iv['id'].'&year='.$taxYear) ?>">
<input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="action" value="evidence-invoice-save"><input type="hidden" name="tab" value="invoices"><input type="hidden" name="year" value="<?= (int)$taxYear ?>"><input type="hidden" name="id" value="<?= (int)$iv['id'] ?>"><input type="hidden" name="version" value="<?= $escape($ivf('version')) ?>">
<?php foreach(['issue_date'=>'Vystavení','delivery_date'=>'Prodej / poskytnutí služby','due_date'=>'Splatnost','paid_date'=>'Skutečná úhrada'] as $key=>$label):?><label><?= $label ?><input type="date" name="<?= $key ?>" value="<?= $escape($ivf($key)) ?>" <?= in_array($key,['issue_date','due_date'],true)?'required':'' ?>></label><?php endforeach;?>
<label>Činnost / e-shop<input name="activity" maxlength="120" value="<?= $escape($ivf('activity')) ?>"></label><label>Variabilní symbol<input name="variable_symbol" maxlength="10" value="<?= $escape($ivf('variable_symbol')) ?>"></label><label>Doprava Kč<input name="shipping_czk" type="number" min="0" max="9999999" value="<?= $escape($ivf('shipping_czk')) ?>" required></label>
<?php foreach(['seller'=>'Dodavatel','buyer'=>'Odběratel'] as $party=>$title):?><fieldset class="panel-evidence-wide"><legend><?= $title ?></legend><div class="panel-evidence-subgrid"><?php foreach(['name'=>'Jméno / název','ico'=>'IČO','street'=>'Ulice','city'=>'Město','postal_code'=>'PSČ','email'=>'E-mail','phone'=>'Telefon','bank_account'=>'Účet'] as $key=>$label):?><label><?= $label ?><input name="<?= $party.'_'.$key ?>" maxlength="190" value="<?= $escape($ivf($party.'_'.$key)) ?>" <?= $key==='name'?'required':'' ?>></label><?php endforeach;?></div></fieldset><?php endforeach;?>
<fieldset class="panel-evidence-wide" data-invoice-items><legend>Položky · ceny v celých Kč</legend><?php foreach(is_array($draft['items']??null)?$draft['items']:[] as $index=>$item):if(!is_array($item))continue;?><div class="evidence-invoice-item"><label>Název<input name="items[<?= (int)$index ?>][name]" value="<?= $escape(is_string($item['name']??null)?$item['name']:'') ?>" required maxlength="255"></label><label>Počet<input type="number" name="items[<?= (int)$index ?>][quantity]" value="<?= (int)($item['quantity']??0) ?>" min="1" max="99999" required></label><label>Cena za kus Kč<input type="number" name="items[<?= (int)$index ?>][unit_price_czk]" value="<?= (int)($item['unit_price_czk']??0) ?>" min="0" max="9999999" required></label><button type="button" class="panel-button" data-remove-invoice-item>Odebrat</button></div><?php endforeach;?><button type="button" class="panel-button" data-add-invoice-item>Přidat položku</button></fieldset>
<label class="panel-evidence-wide">Důvod přímé změny<input name="reason" value="<?= $escape($ivf('reason')) ?>" maxlength="190" required></label><label class="panel-check panel-evidence-wide"><input type="checkbox" name="acknowledged" value="1" required> Chci přímo upravit vystavenou fakturu. Ověřím dopad na předané doklady a evidenci plateb.</label><button class="panel-button">Uložit novou verzi faktury</button></form></details>
<?php if($invoiceEditHistory!==[]):?><details class="panel-panel"><summary>Historie změn obsahu faktury</summary><?php foreach($invoiceEditHistory as $event):?><details><summary><?= $escape($event['created_at'].' · '.$event['reason']) ?></summary><div class="panel-audit-values"><pre><?= $escape(json_encode(json_decode($event['old_json'],true),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)) ?></pre><pre><?= $escape(json_encode(json_decode($event['new_json'],true),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)) ?></pre></div></details><?php endforeach;?></details><?php endif;?>

<script>
(()=>{const list=document.querySelector('[data-invoice-items]');if(!list)return;let next=Math.max(-1,...[...list.querySelectorAll('input[name]')].map(e=>Number(e.name.match(/items\[(\d+)\]/)?.[1]??-1)))+1;
list.addEventListener('click',event=>{if(event.target.matches('[data-remove-invoice-item]')){event.target.closest('.evidence-invoice-item').remove();return;}
if(event.target.matches('[data-add-invoice-item]')){const row=document.createElement('div');row.className='evidence-invoice-item';const fields=[['name','Název','text','',null,null],['quantity','Počet','number','1','1','99999'],['unit_price_czk','Cena za kus Kč','number','0','0','9999999']];for(const [key,title,type,value,min,max] of fields){const label=document.createElement('label');label.textContent=title;const input=document.createElement('input');Object.assign(input,{name:`items[${next}][${key}]`,type,value,required:true});if(min!==null){input.min=min;input.max=max;}else input.maxLength=255;label.append(input);row.append(label);}const remove=document.createElement('button');remove.type='button';remove.className='panel-button';remove.dataset.removeInvoiceItem='';remove.textContent='Odebrat';row.append(remove);list.insertBefore(row,event.target);row.querySelector('input').focus();next++;}});})();
</script>
